// Custom Worker entry: wraps the OpenNext-generated worker and adds a cron
// trigger (see "triggers" in wrangler.jsonc) that keeps Supabase from pausing
// the project for inactivity.
// https://opennext.js.org/cloudflare/howtos/custom-worker

// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- file only exists after a build
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Ctx = { waitUntil(promise: Promise<unknown>): void };

const worker = {
  fetch: handler.fetch,

  async scheduled(_event: unknown, env: unknown, ctx: Ctx) {
    // Route through the app itself so the ping uses the same Supabase
    // credentials as every other request, whichever way they were configured.
    const run = async () => {
      const res: Response = await handler.fetch(new Request("https://keepalive.internal/api/keepalive"), env, ctx);
      if (!res.ok) throw new Error(`keepalive returned ${res.status}: ${await res.text()}`);
      console.log("[keepalive] ok");
    };
    ctx.waitUntil(run());
  },
};

export default worker;

// Durable Objects the generated worker exports; they must be re-exported here.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated at build time
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
